import React, { useState, useRef, useEffect } from 'react';
import axios from 'axios';
import { initWebGL, processFrameWebGL } from '../utils/webglProcessor';

const API_URL = 'http://localhost:5000/api';

const CameraProcessor = ({ colorblindType, mode }) => {
  const [streaming, setStreaming] = useState(false);
  const [error, setError] = useState(null);
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const glRef = useRef(null);
  const streamRef = useRef(null);
  const animationFrameRef = useRef(null);

  useEffect(() => {
    return () => {
      stopCamera();
    };
  }, []);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { width: 1280, height: 720 }
      });
      
      streamRef.current = stream;
      
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play();
        setStreaming(true);
        setError(null);
        
        // Initialize WebGL
        if (canvasRef.current) {
          const gl = initWebGL(canvasRef.current);
          glRef.current = gl;
          
          // Start processing frames
          processFrames();
        }
      }
    } catch (err) {
      setError('Failed to access camera: ' + err.message);
      setStreaming(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }
    
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    
    setStreaming(false);
  };

  const processFrames = async () => {
    if (!videoRef.current || !canvasRef.current || !streaming) return;
    
    const video = videoRef.current;
    const canvas = canvasRef.current;
    
    if (video.readyState === video.HAVE_ENOUGH_DATA) {
      // Use WebGL for real-time processing if available
      if (glRef.current) {
        processFrameWebGL(glRef.current, video, canvas, colorblindType, mode);
      } else {
        // Fallback to canvas processing
        const ctx = canvas.getContext('2d');
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        
        // Apply color transformation using canvas
        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        const data = imageData.data;
        
        // Simple color transformation
        for (let i = 0; i < data.length; i += 4) {
          const r = data[i];
          const g = data[i + 1];
          const b = data[i + 2];
          
          if (mode === 'simulate') {
            if (colorblindType === 'protanopia') {
              // Protanopia simulation
              data[i] = r * 0.567 + g * 0.433;
              data[i + 1] = r * 0.558 + g * 0.442;
              data[i + 2] = g * 0.242 + b * 0.758;
            } else if (colorblindType === 'deuteranopia') {
              // Deuteranopia simulation
              data[i] = r * 0.625 + g * 0.375;
              data[i + 1] = r * 0.700 + g * 0.300;
              data[i + 2] = g * 0.300 + b * 0.700;
            }
          } else {
            // Enhancement mode - increase contrast
            const avg = (r + g + b) / 3;
            const factor = 1.2;
            data[i] = Math.min(255, avg + (r - avg) * factor);
            data[i + 1] = Math.min(255, avg + (g - avg) * factor);
            data[i + 2] = Math.min(255, avg + (b - avg) * factor);
          }
        }
        
        ctx.putImageData(imageData, 0, 0);
      }
    }
    
    animationFrameRef.current = requestAnimationFrame(processFrames);
  };

  useEffect(() => {
    if (streaming && videoRef.current) {
      processFrames();
    }
  }, [streaming, colorblindType, mode]);

  return (
    <div className="component-container">
      <h2>Live Camera Processor</h2>
      
      {error && <div className="error">{error}</div>}
      
      <div className="camera-container">
        <video
          ref={videoRef}
          className="camera-video"
          style={{ display: streaming ? 'block' : 'none' }}
          width="800"
          height="600"
          playsInline
        />
        <canvas
          ref={canvasRef}
          className="camera-video"
          style={{ display: streaming ? 'block' : 'none' }}
          width="800"
          height="600"
        />
        {!streaming && (
          <div className="upload-area" style={{ minHeight: '400px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <p>Click "Start Camera" to begin live processing</p>
          </div>
        )}
      </div>

      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        {!streaming ? (
          <button className="button" onClick={startCamera}>
            Start Camera
          </button>
        ) : (
          <button className="button" onClick={stopCamera}>
            Stop Camera
          </button>
        )}
      </div>
    </div>
  );
};

export default CameraProcessor;
